package com.example.bookstore.controller;
import com.example.bookstore.dto.*; import com.example.bookstore.service.AuthorService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/authors") public class AuthorController { private final AuthorService service; public AuthorController(AuthorService service){this.service=service;} @PostMapping ResponseEntity<AuthorResponse> create(@Valid @RequestBody AuthorRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping List<AuthorResponse> all(){return service.findAll();} @GetMapping("/{id}") AuthorResponse one(@PathVariable Long id){return AuthorResponse.from(service.get(id));} @PutMapping("/{id}") AuthorResponse update(@PathVariable Long id,@Valid @RequestBody AuthorRequest r){return service.update(id,r);} @DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();} }
